func (v *users) ShowParametersDetails(ctx context.Context, id AccountObjectIdentifier) (*UserParametersDetails, error) {
	params, err := v.ShowParameters(ctx, id)
	if err != nil {
		return nil, err
	}
	return toUserParametersDetails(params)
}
